from queueing import payload

def submit(owner, enqueue, region="worldwide"):
    return enqueue(payload(owner, region))

def execute(task, collect):
    region = task.get("region", "worldwide")
    if region not in ["worldwide", "europe", "americas"]:
        raise ValueError(f"Invalid region: {region}. Allowed values are: worldwide, europe, americas.")
    return collect(task["owner"], region)
